const fs=require('node:fs/promises');const path=require('node:path');const PptxGenJS=require('pptxgenjs');
const cases=[
 {id:'elementary-language',level:'國小高年級／語文',style:'notebook',title:'同一件事，可以怎麼說？',a:'請把窗戶關上。',b:'可以請你幫忙關窗嗎？',answer:'比較語氣，再說明你會在什麼情境使用。'},
 {id:'junior-history',level:'國中／歷史',style:'timeline',title:'兩份史料，描述一樣嗎？',a:'史料甲：活動讓街道更熱鬧。',b:'史料乙：活動讓居民難以通行。',answer:'這是自撰情境。比較作者立場與觀察範圍，不急著判定誰對誰錯。'},
 {id:'high-math',level:'高中／數學',style:'math',title:'把相等關係畫出來',a:'x + 2 = 5',b:'兩邊同減 2',answer:'x = 3。代回原式：3 + 2 = 5。此為基礎推理示例，正式高中教材需依目標加深。'},
 {id:'university-art',level:'大學／藝術',style:'museum',title:'構圖如何分配視覺重量？',a:'對稱構圖',b:'不對稱構圖',answer:'觀察元素的位置、大小與留白，再說明你的視覺判斷。'}
];
const esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
async function main(){const out=path.resolve(process.argv[2]);await fs.mkdir(out,{recursive:true});const styles=JSON.parse(await fs.readFile(path.join(__dirname,'../../ui/styles.json'),'utf8'));
 for(const c of cases){const t=styles.find(s=>s.id===c.style),color=t.accent.slice(1),ink=t.ink.slice(1);const p=new PptxGenJS();p.layout='LAYOUT_WIDE';p.author='黑熊老師';p.title=c.title;p.theme={headFontFace:'Microsoft JhengHei',bodyFontFace:'Microsoft JhengHei',lang:'zh-TW'};
 for(let n=0;n<2;n++){const s=p.addSlide();s.background={color:t.background.slice(1)};s.addText(c.level+' · 自撰工具驗證示例',{x:.7,y:.4,w:12,h:.4,fontSize:16,color});s.addText(n===0?c.title:'說明你的判斷',{x:.7,y:1.1,w:12,h:.8,fontSize:30,bold:true,color:ink});
 if(n===0){for(const [i,txt]of [c.a,c.b].entries()){const x=.8+i*6.1;s.addShape(p.ShapeType.rect,{x,y:2.4,w:5.6,h:2,line:{color},fill:{color:t.background.slice(1)}});s.addText(txt,{x:x+.2,y:2.7,w:5.2,h:1.3,fontSize:24,color:ink});}s.addText('→ 查看討論',{x:.8,y:5.4,w:4,h:.5,fontSize:22,color,hyperlink:{slide:2}})}else{s.addText(c.answer,{x:.8,y:2.5,w:11.7,h:2,fontSize:26,color:ink});s.addText('← 返回問題',{x:.8,y:5.4,w:4,h:.5,fontSize:22,color,hyperlink:{slide:1}})}s.addNotes('工具驗證案例，非完整正式課程。')}await p.writeFile({fileName:path.join(out,c.id+'.pptx')});
 const svg=`<svg viewBox="0 0 900 240" role="img" aria-label="比較兩種表達"><rect x="15" y="25" width="395" height="190" fill="none" stroke="${t.accent}" stroke-width="3"/><rect x="490" y="25" width="395" height="190" fill="none" stroke="${t.accent}" stroke-width="3"/><path d="M425 120H475" stroke="${t.accent}" stroke-width="4"/><text x="40" y="120" fill="${t.ink}" font-size="26">${esc(c.a.slice(0,12))}<tspan x="40" dy="36">${esc(c.a.slice(12))}</tspan></text><text x="515" y="120" fill="${t.ink}" font-size="26">${esc(c.b.slice(0,12))}<tspan x="515" dy="36">${esc(c.b.slice(12))}</tspan></text></svg>`;
 const html=`<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(c.title)}</title><style>body{margin:0;background:${t.background};color:${t.ink};font-family:Microsoft JhengHei,sans-serif}main{max-width:1100px;margin:40px auto;padding:30px}h1{font-size:42px}p{font-size:24px}svg{width:100%}button{font:inherit;font-size:22px;padding:14px;color:${t.ink};background:none;border:2px solid ${t.accent};cursor:pointer}#answer{border-left:5px solid ${t.accent};padding:20px}</style><main><p>${esc(c.level)} · 自撰工具驗證示例</p><h1>${esc(c.title)}</h1>${svg}<button id="reveal" aria-expanded="false">查看討論</button><p id="answer" hidden>${esc(c.answer)}</p></main><script>document.querySelector('button').onclick=function(){const a=document.querySelector('#answer');a.hidden=!a.hidden;this.setAttribute('aria-expanded',String(!a.hidden))}</script></html>`;
 await fs.writeFile(path.join(out,c.id+'.html'),html);
 }console.log('Created four cross-domain HTML/PPTX pairs (scripted engine fixtures, not agent-generated content).');}
main().catch(e=>{console.error(e);process.exitCode=1});
